import{_ as a,o as t,c as r,a0 as s}from"./chunks/framework.C4u0TEY0.js";const u=JSON.parse('{"title":"Architecture","description":"","frontmatter":{},"headers":[],"relativePath":"internals/architecture.md","filePath":"internals/architecture.md"}'),n={name:"internals/architecture.md"};function i(o,e,d,c,l,h){return t(),r("div",null,[...e[0]||(e[0]=[s(`<h1 id="architecture" tabindex="-1">Architecture <a class="header-anchor" href="#architecture" aria-label="Permalink to &quot;Architecture&quot;">​</a></h1><p>apk.js is layered. Each layer hands a narrower representation to the next.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>APK zip</span></span>
<span class="line"><span>  └── parser        dex/, res/      bytes → classes, resources, layouts</span></span>
<span class="line"><span>        └── runtime  runtime/       DEX → JavaVM, objects, interpreter</span></span>
<span class="line"><span>              └── framework          Java API calls → view tree and pixels</span></span>
<span class="line"><span>                    └── engine       lifecycle, screen, input</span></span></code></pre></div><h2 id="layers" tabindex="-1">Layers <a class="header-anchor" href="#layers" aria-label="Permalink to &quot;Layers&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Layer</th><th>Directory</th><th>Responsibility</th></tr></thead><tbody><tr><td>Parser</td><td><code>src/dex</code>, <code>src/res</code></td><td>Read binary formats: DEX, AXML, ARSC</td></tr><tr><td>Runtime</td><td><code>src/runtime</code></td><td>Class registry, value model, bytecode interpreter</td></tr><tr><td>Framework</td><td><code>src/framework</code></td><td>Android API surface backed by Canvas and JavaScript</td></tr><tr><td>Entry</td><td><code>apk.js</code></td><td>Public API, device setup, file loading</td></tr></tbody></table><h2 id="runtime" tabindex="-1">Runtime <a class="header-anchor" href="#runtime" aria-label="Permalink to &quot;Runtime&quot;">​</a></h2><p><code>JavaVM</code> owns the class registry, the interpreter, the heap and the method stack. Values are JavaScript objects with a descriptor: <code>JavaObject</code> for instances, <code>JavaArray</code> for arrays, and plain numbers or strings for primitives.</p><p><code>DexInterpreter</code> walks bytecode, maintaining a register file per frame. It dispatches method calls back into the VM, which resolves them against native definitions first and then against DEX classes.</p><h2 id="framework" tabindex="-1">Framework <a class="header-anchor" href="#framework" aria-label="Permalink to &quot;Framework&quot;">​</a></h2><p>The framework is a set of native class definitions. Each one implements a slice of an Android class in terms of JavaScript and the Canvas 2D API. A <code>View</code> holds geometry, layout params and a draw method; a <code>ViewGroup</code> additionally knows how to measure and arrange children.</p><p>The engine wires the framework to a canvas: it creates the initial activity, drives <code>onCreate</code>, drains the choreographer loop, and routes pointer events into the view tree.</p><h2 id="engine" tabindex="-1">Engine <a class="header-anchor" href="#engine" aria-label="Permalink to &quot;Engine&quot;">​</a></h2><p><code>EmulatorEngine.start(apk)</code> sets up the VM, registers native classes, seeds the virtual filesystem, installs sensor sources, and launches the launcher activity. <code>attachCanvas</code> binds a canvas for rendering and input.</p><p>The screen tracks dirty state. When a view calls <code>invalidate</code>, the engine marks the screen dirty and repaints on the next frame.</p>`,14)])])}const m=a(n,[["render",i]]);export{u as __pageData,m as default};
